sed -i 's/expected YYYY-MM-DD)" >\&2; exit 1; fi/expected YYYY-MM-DD)" >\&2; exit 2; fi/' src/list.sh && grep -n 'exit 2; fi' src/list.sh
cat > src/remind.sh <<'EOF'
#!/bin/bash
# remind.sh DATE: one reminder per booking of the day, from the listing (remind.sh and list.sh both check DATE).
set -u
if [ -n "${1:-}" ] && ! [[ "$1" =~ ^[0-9]{4}-[0-9]{2}-[0-9]{2}$ ]]; then echo "bad date: $1 (expected YYYY-MM-DD)" >&2; exit 2; fi
out=$(bash "$(dirname "$0")/list.sh" "$@") || exit $?
[ -z "$out" ] || printf '%s\n' "$out" | while read -r d t r w; do echo "reminder to $w: $r $d $t"; done
EOF
cat > spec/list_date.spec.sh <<'EOF'
#!/bin/bash
fail=0
t=$(mktemp); printf '# room\tdate\tstart\tend\twho\naoi\t2026-01-02\t10:00\t11:00\tx\n' > "$t"
BOOKINGS=$t bash src/list.sh 2026/01/01 >/dev/null 2>&1; [ $? = 2 ] || { echo "a malformed date should exit 2"; fail=1; }
[ "$(BOOKINGS=$t bash src/list.sh 2026/01/01 2>&1 >/dev/null)" = 'bad date: 2026/01/01 (expected YYYY-MM-DD)' ] || { echo "bad date message"; fail=1; }
BOOKINGS=$t bash src/list.sh 2026-01-02 >/dev/null 2>&1; [ $? = 0 ] || { echo "a well-formed date should exit 0"; fail=1; }
rm -f "$t"; exit $fail
EOF
cat > spec/remind_date.spec.sh <<'EOF'
#!/bin/bash
fail=0
t=$(mktemp); printf '# room\tdate\tstart\tend\twho\naoi\t2026-01-02\t10:00\t11:00\tx\n' > "$t"
BOOKINGS=$t bash src/remind.sh 2026/01/02 >/dev/null 2>&1; [ $? = 2 ] || { echo "remind: a malformed date should exit 2"; fail=1; }
[ "$(BOOKINGS=$t bash src/remind.sh 2026/01/02 2>&1 >/dev/null)" = 'bad date: 2026/01/02 (expected YYYY-MM-DD)' ] || { echo "remind: bad date message"; fail=1; }
[ "$(BOOKINGS=$t bash src/remind.sh 2026-01-02)" = 'reminder to x: aoi 2026-01-02 10:00' ] || { echo "remind: well-formed date"; fail=1; }
rm -f "$t"; exit $fail
EOF
